import { expect, test } from 'claude-code/testing'

// Generated by tools/build.py from shared/single.test.template.ts: edit that.
const PLUGIN = 'night-hearth'
const FIRST = 'night-hearth'
const SECOND = undefined as { version: string; scene: string } | undefined

const start = { cwd: '/tmp', surface: 'desktop' as const, isInteractive: true }
const run = (args: string) => ({
  command: PLUGIN,
  args,
  origin: { kind: 'composer' as const },
  presentation: { isFullscreen: false, columns: 100 },
})

test('a new session shows it, other versions switch, off clears it, and the choice is remembered', async ($, on) => {
  const stored: Record<string, unknown> = {}
  const shown: string[] = []
  let cleared = 0
  on('store.get', (_, e) => ({ value: stored[e.key] }))
  on('store.set', (_, e) => {
    stored[e.key] = e.value
    return { value: undefined }
  })
  on('command.register', () => ({ value: { command: PLUGIN } }))
  on('session.start', () => ({ cwd: '/tmp' }))
  on('theme.set', (_, e) => {
    const backdrop = e.backdrop
    shown.push((backdrop !== undefined && 'scene' in backdrop ? backdrop.scene : undefined) ?? '?')
    return { value: { isDrawn: true, requestId: 'r1' } }
  })
  on('theme.clear', () => {
    cleared += 1
    return { value: { isDrawn: true, requestId: 'r2' } }
  })

  await $.session.start(start)
  expect(shown).toEqual([FIRST])

  if (SECOND !== undefined) {
    await $.command.run(run(SECOND.version))
    expect(shown.at(-1)).toBe(SECOND.scene)
    expect(stored.choice).toBe(SECOND.scene)
  }

  const off = await $.command.run(run('off'))
  expect(off.text).toContain('off')
  expect(cleared).toBe(1)
  expect(stored.choice).toBe('off')
})

test('the backdrop draws one picture', async ($) => {
  const ui = await $.ui.mount({
    plugin: PLUGIN,
    component: 'Backdrop',
    requestId: 'bd',
    props: { scene: FIRST, plugin: PLUGIN, glass: { blur: 0, opacity: 0 } },
    surface: 'desktop',
  })
  expect((await ui.findAll({ type: 'Svg' })).length).toBe(1)
  await ui.unmount()
})
